<?php $title='Posts';require __DIR__.'/_layout.php';if(!can_manage('posts'))exit('Forbidden');if(isset($_GET['delete'])&&can_manage('posts')){db()->prepare("DELETE FROM posts WHERE id=?")->execute([(int)$_GET['delete']]);flash('success','Post deleted.');redirect('posts.php');}$rows=db()->query("SELECT p.*,c.name category,u.name author FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN users u ON u.id=p.author_id ORDER BY p.created_at DESC")->fetchAll();?><div class="toolbar"><h1>Posts</h1><a class="btn" href="post-create.php">Add post</a></div><table class="table"><tr><th>Title</th><th>Status</th><th>Author</th><th>Views</th><th>Actions</th></tr><?php foreach($rows as $p):?><tr><td><?=e($p['title'])?></td><td><?=e($p['status'])?></td><td><?=e($p['author'])?></td><td><?=e($p['view_count'])?></td><td><a href="post-edit.php?id=<?=$p['id']?>">Edit</a> · <a data-confirm="Delete this post?" href="posts.php?delete=<?=$p['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>